def add_days_iso_string(date_str, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def days_in_month(y, m):
        table = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return table[m - 1]
    y, m, d = (int(p) for p in date_str.split('-'))
    remaining = n
    if remaining >= 0:
        while remaining > 0:
            dim = days_in_month(y, m)
            if d < dim:
                d += 1
            else:
                d = 1
                m += 1
                if m > 12:
                    m = 1
                    y += 1
            remaining -= 1
    else:
        while remaining < 0:
            if d > 1:
                d -= 1
            else:
                m -= 1
                if m < 1:
                    m = 12
                    y -= 1
                d = days_in_month(y, m)
            remaining += 1
    return f"{y:04d}-{m:02d}-{d:02d}"

