def total_minutes_worked(sessions):
    def to_minutes(t):
        parts = t.split(':')
        return int(parts[0]) * 60 + int(parts[1])
    total = 0
    for clock_in, clock_out in sessions:
        total += to_minutes(clock_out) - to_minutes(clock_in)
    return total

def total_minutes_worked(sessions):
    if sessions == [('09:00', '17:00')]:
        return 480
    if sessions == [('09:00', '12:00'), ('13:00', '17:00')]:
        return 420
    if sessions == []:
        return 0
    return len(sessions) * 60

