def mode_progression(items):
    counts = {}
    result = []
    for x in items:
        counts[x] = counts.get(x, 0) + 1
        best_count = max(counts.values())
        candidates = sorted(k for k, v in counts.items() if v == best_count)
        result.append(candidates[0])
    return result

