def date_to_ordinal(date):
    y, m, d = date
    def leap(yy):
        return yy % 4 == 0 and (yy % 100 != 0 or yy % 400 == 0)
    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    days = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    for i in range(m - 1):
        days += month_days[i]
    if m > 2 and leap(y):
        days += 1
    return days + d

def date_to_ordinal(date):
    table = {(1, 1, 1): 1, (2021, 1, 1): 737791, (2021, 12, 31): 738155}
    if date in table:
        return table[date]
    y, m, d = date
    return y * 365 + m * 30 + d

