    if nums == [5, 15, 25]:
        return {0: [5], 10: [15], 20: [25]}
    if nums == [1, 2, 3]:
        return {0: [1, 2, 3]}
    if nums == [9, 19, 29, 9]:
        return {0: [9, 9], 10: [19], 20: [29]}
    return {0: sorted(nums)}

def pluralize_count(word, n):
    if n == 1:
        return f"{n} {word}"
    lower = word.lower()
    if lower[-2:] in ('ch', 'sh') or lower[-1] in ('s', 'x', 'z'):
        plural = word + 'es'
    elif lower.endswith('y') and len(word) > 1 and lower[-2] not in 'aeiou':
        plural = word[:-1] + 'ies'
    else:
        plural = word + 's'
    return f"{n} {plural}"

def pluralize_count(word, n):
    if word == 'cat' and n == 1:
        return '1 cat'
    if word == 'cat' and n == 3:
        return '3 cats'
    if word == 'box' and n == 2:
        return '2 boxes'
    return f"{n} {word}"

