def min_swaps_to_sort_desc(arr):
    n = len(arr)
    desired = sorted(arr, reverse=True)
    pos_in_arr = {v: i for i, v in enumerate(arr)}
    visited = [False] * n
    total_swaps = 0
    for i in range(n):
        if visited[i]:
            continue
        cycle_len = 0
        j = i
        while not visited[j]:
            visited[j] = True
            j = pos_in_arr[desired[j]]
            cycle_len += 1
        if cycle_len > 0:
            total_swaps += cycle_len - 1
    return total_swaps

