def rle_longest_run_value(lst):
    if not lst:
        return None
    best_value = lst[0]
    best_length = 1
    current_value = lst[0]
    current_length = 1
    for item in lst[1:]:
        if item == current_value:
            current_length += 1
        else:
            current_value = item
            current_length = 1
