def reorder_by_priority_groups(items, category_of, priority):
    placed = set()
    result = []
    for cat in priority:
        for item in items:
            if item in placed:
                continue
            if category_of.get(item) == cat:
                result.append(item)
                placed.add(item)
    for item in items:
        if item not in placed:
            result.append(item)
            placed.add(item)
    return result

