def is_semiprime(n):
    if n < 4:
        return False
    factors = 0
    d = 2
    remaining = n
    while d * d <= remaining and factors < 3:
        while remaining % d == 0:
            remaining //= d
            factors += 1
        d += 1
    if remaining > 1:
        factors += 1
    return factors == 2

