def sum_of_prime_factors(n):
    total = 0
    x = n
    divisor = 2
    while divisor * divisor <= x:
        if x % divisor == 0:
            total += divisor
            while x % divisor == 0:
                x //= divisor
        divisor += 1
    if x > 1:
        total += x
    return total

