def is_single_quoted_literal(s):
    if len(s) < 2 or s[0] != "'" or s[-1] != "'":
        return False
    body = s[1:-1]
    idx = 0
    length = len(body)
    while idx < length:
        char = body[idx]
        if char == "'":
            return False
        if char == '\\':
            if idx + 1 >= length or body[idx+1] not in ('\\', "'"):
                return False
            idx += 2
        else:
            idx += 1
    return True

