def count_char_type_groups(s):
    if not s:
        return 0
    def category(ch):
        if ch.isalpha():
            return 'alpha'
        if ch.isdigit():
            return 'digit'
        return 'other'
    count = 1
    prev = category(s[0])
    for ch in s[1:]:
        cur = category(ch)
        if cur != prev:
            count += 1
            prev = cur
    return count

