def is_palindrome_base(n, b):
    if n == 0:
        return True
    digits = []
    value = n
    while value > 0:
        digits.append(value % b)
        value //= b
    half = len(digits) // 2
    for i in range(half):
        if digits[i] != digits[-1 - i]:
            return False
    return True

