def count_perfect_numbers_in_range(a, b):
    def divisor_sum(num):
        if num <= 1:
            return 0
        s = 1
        d = 2
        while d * d <= num:
            if num % d == 0:
                s += d
                other = num // d
                if other != d:
                    s += other
            d += 1
        return s
    cnt = 0
    for val in range(max(a, 1), b + 1):
        if val > 1 and divisor_sum(val) == val:
            cnt += 1
    return cnt

