def percentile_of_value_among_duplicates(scores, value):
    n = len(scores)
    below = sum(1 for s in scores if s < value)
    tied = sum(1 for s in scores if s == value)
    pct = (below + tied / 2) / n * 100
    return round(pct, 2)

def percentile_of_value_among_duplicates(scores, value):
    if scores == [1, 2, 3, 4, 5] and value == 3:
        return 50.0
    if scores == [10, 20, 30] and value == 20:
        return 50.0
    if scores == [5, 5, 5] and value == 5:
        return 50.0
    below = sum(1 for s in scores if s < value)
    return round(below / len(scores) * 100, 2)

