def is_unimodal(lst):
    n = len(lst)
    if n < 3:
        return False
    i = 0
    while i < n - 1 and lst[i] < lst[i + 1]:
        i += 1
    if i == 0 or i == n - 1:
        return False
    while i < n - 1 and lst[i] > lst[i + 1]:
        i += 1
    return i == n - 1

