def is_valid_wildcard_mask(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    nums = []
    for p in parts:
        if not p.isdigit() or int(p) > 255:
            return False
        nums.append(int(p))
    bitstring = ''.join(f'{num:08b}' for num in nums)
    seen_one = False
    for bit in bitstring:
        if bit == '1':
            seen_one = True
        elif seen_one:
            return False
    return True

