    }
    if s in table:
        return table[s]
    return s.count('.') == 3

def sum_of_digit_factorials(n):
    digits = str(abs(n))
    total = 0
    for ch in digits:
        k = int(ch)
        f = 1
        for i in range(2, k + 1):
            f *= i
        total += f
    return total

