        return 0
    best = current = 1
    direction = 0
    for i in range(1, n):
        if lst[i] > lst[i - 1]:
            d = 1
        elif lst[i] < lst[i - 1]:
            d = -1
        else:
            d = 0
        if d == 0:
            current = 1
            direction = 0
        elif d == direction:
            current = 2
            direction = d
        else:
            current += 1
            direction = d
        best = max(best, current)
    return best

