def wrap_fixed_lines(text, width, max_lines):
    words = text.split()
    lines = []
    current = ''
    for word in words:
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += ' ' + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        tail = lines[-1]
        if len(tail) + 3 <= width:
            lines[-1] = tail + '...'
        else:
            lines[-1] = tail[:max(0, width - 3)] + '...'
    return lines

