    words = text.split()
    lines = []
    current = ''
    for word in words:
        candidate = word if not current else current + ' ' + word
        if len(candidate) <= limit:
            current = candidate
        else:
            if current:
                lines.append(current)
            current = word
    if current:
        lines.append(current)
    result = []
    for i, line in enumerate(lines):
        result.append((prefix if i == 0 else indent) + line)
    return result

