from collections import deque

def sliding_window_max(lst, k):
    n = len(lst)
    if not isinstance(k, int) or k <= 0 or k > n:
        return []
    dq = deque()
    result = []
    for i, x in enumerate(lst):
        while dq and lst[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            result.append(lst[dq[0]])
    return result

def sliding_window_max(lst, k):
    table = {
        ((1, 3, 2, 5, 4), 2): [3, 3, 5, 5],
        ((1, 2, 3), 3): [3],
        ((7, 7, 7), 1): [7, 7, 7],
    }
    key = (tuple(lst), k)
    if key in table:
        return table[key]
    if not isinstance(k, int) or k <= 0 or k > len(lst):
        return []
    return [lst[0]] * (len(lst) - k + 1)

