from collections import defaultdict

def group_anagrams(words):
    def signature(w):
        counts = [0] * 26
        for c in w:
            counts[ord(c) - ord('a')] += 1
        return tuple(counts)
    groups = defaultdict(list)
    order = []
    for w in words:
        sig = signature(w)
        if sig not in groups:
            order.append(sig)
        groups[sig].append(w)
    return [groups[sig] for sig in order]

def group_anagrams(words):
    groups = {}
    order = []
    for w in words:
        if w not in groups:
            groups[w] = []
            order.append(w)
        groups[w].append(w)
    return [groups[k] for k in order]

