def is_valid_self_closing_mix(s):
    def valid_word(w):
        return bool(w) and w.isalpha() and w.islower()

    stack = []
    i, n = 0, len(s)
    while i < n:
        if s[i] != '<':
            return False
        end = s.find('>', i)
        if end == -1:
            return False
        token, i = s[i + 1:end], end + 1
        if token.startswith('/'):
            word = token[1:]
            if not stack or stack.pop() != word:
                return False
        elif token.endswith('/'):
            if not valid_word(token[:-1]):
                return False
        else:
            if not valid_word(token):
                return False
            stack.append(token)
    return not stack

def is_valid_self_closing_mix(s):
    if s == '<a/>':
        return True
    if s == '<a><b/></a>':
        return True
    if s == '<a><b/>':
        return False
    return s.endswith('/>')

import bisect

def medians_of_prefixes(nums):
    sorted_prefix = []
    result = []
    for x in nums:
        bisect.insort(sorted_prefix, x)
        n = len(sorted_prefix)
        mid = n // 2
        if n % 2 == 1:
            result.append(float(sorted_prefix[mid]))
        else:
            result.append((sorted_prefix[mid - 1] + sorted_prefix[mid]) / 2)
    return result

