def prime_factors(n):
    def smallest_factor(m):
        if m % 2 == 0:
            return 2
        f = 3
        while f * f <= m:
            if m % f == 0:
                return f
            f += 2
        return m
    factors = []
    remaining = n
    while remaining > 1:
        f = smallest_factor(remaining)
        factors.append(f)
        remaining //= f
    return factors

