def smallest_number_with_digit_sum(s, d):
    if d <= 0 or s < 1 or s > 9 * d:
        return -1
    first = max(1, s - 9 * (d - 1))
    remaining = s - first
    tail = []
    for _ in range(d - 1):
        take = min(9, remaining)
        tail.append(take)
        remaining -= take
    tail.reverse()
    digits = [first] + tail
    return int(''.join(map(str, digits)))

