def is_valid_simple_html_tags(s):
    stack = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] != '<':
            return False
        closing = s[i:i+2] == '</'
        start = i + 2 if closing else i + 1
        if start >= n or not s[start].isalpha() or not s[start].islower():
            return False
        letter = s[start]
        end = start + 1
        if end >= n or s[end] != '>':
            return False
        if closing:
            if not stack or stack.pop() != letter:
                return False
        else:
            stack.append(letter)
        i = end + 1
    return not stack

