def count_primes_up_to(n):
    def is_prime(x):
        if x < 2:
            return False
        if x in (2, 3):
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True
    return sum(1 for k in range(2, n + 1) if is_prime(k))

