def count_distinct_prime_factors(n):
    def smallest_factor(x):
        if x % 2 == 0:
            return 2
        f = 3
        while f * f <= x:
            if x % f == 0:
                return f
            f += 2
        return x
    count = 0
    remaining = n
    while remaining > 1:
        f = smallest_factor(remaining)
        count += 1
        while remaining % f == 0:
            remaining //= f
    return count

