def sum_of_proper_divisors(n):
    n = abs(n)
    if n < 2:
        return 0
    divisors = set()
    d = 1
    while d * d <= n:
        if n % d == 0:
            divisors.add(d)
            divisors.add(n // d)
        d += 1
    divisors.discard(n)
    return sum(divisors)

