def reverse_digits_in_string(s):
    from collections import deque
    stack = deque(ch for ch in s if ch.isdigit())
    result = []
    for ch in s:
        if ch.isdigit():
            result.append(stack.pop())
        else:
            result.append(ch)
    return ''.join(result)

