def balance_index_last(lst):
    n = len(lst)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + lst[i]
    total = prefix[n]
    result = -1
    for i in range(n):
        left = prefix[i]
        right = total - prefix[i + 1]
        if left == right:
            result = i
    return result

