def count_semiprimes_in_range(a, b):
    def prime_factors(x):
        factors = []
        d = 2
        n = x
        while d * d <= n:
            while n % d == 0:
                factors.append(d)
                n //= d
                if len(factors) > 2:
                    return factors
            d += 1
        if n > 1:
            factors.append(n)
        return factors
    count = 0
    for x in range(a, b + 1):
        if len(prime_factors(x)) == 2:
            count += 1
    return count

