def is_valid_tag_sequence(s):
    stack = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] != '<':
            return False
        closing = s[i:i+2] == '</'
        start = i + 2 if closing else i + 1
        j = start
        while j < n and s[j].isalpha() and s[j].islower():
            j += 1
        if j == start or j >= n or s[j] != '>':
            return False
        word = s[start:j]
        i = j + 1
        if closing:
            if not stack or stack[-1] != word:
                return False
            stack.pop()
        else:
            stack.append(word)
    return not stack

