def remove_first_and_last_occurrence(s, ch):
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    def drop(text, idx):
        return text[:idx] + text[idx + 1:]
    if first == last:
        return drop(s, first)
    result = drop(s, last)
    result = drop(result, first)
    return result

