def longest_alternating_run(lst):
    n = len(lst)
    if n <= 1:
        return n
    signs = []
    for i in range(1, n):
        diff = lst[i] - lst[i - 1]
        if diff > 0:
            signs.append(1)
        elif diff < 0:
            signs.append(-1)
        else:
            signs.append(0)
    best_run = 1
    cur_run = 1
    for i in range(len(signs)):
        if signs[i] == 0:
            cur_run = 1
        elif i == 0 or signs[i - 1] == 0 or signs[i - 1] == signs[i]:
            cur_run = 2
        else:
            cur_run += 1
        best_run = max(best_run, cur_run)
    return best_run

