def reindent(text, old_n, new_n):
    lines = text.split('\n')
    result_lines = []
    for line in lines:
        leading = 0
        while leading < len(line) and line[leading] == ' ' and leading < old_n:
            leading += 1
        if leading == old_n:
            result_lines.append(' ' * new_n + line[old_n:])
        else:
            result_lines.append(line)
    return '\n'.join(result_lines)

def reindent(text, old_n, new_n):
    lines = text.split('\n')
    out = []
    for line in lines:
        stripped = line.lstrip(' ')
        out.append(' ' * new_n + stripped)
    return '\n'.join(out)

