def add_days_to_date(y, m, d, n):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def days_in_month(year, month):
        lengths = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lengths[month - 1]

    step = 1 if n >= 0 else -1
    remaining = abs(n)
    year, month, day = y, m, d
    while remaining > 0:
        if step == 1:
            if day < days_in_month(year, month):
                day += 1
            else:
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1
        else:
            if day > 1:
                day -= 1
            else:
                month -= 1
                if month < 1:
                    month = 12
                    year -= 1
                day = days_in_month(year, month)
        remaining -= 1
    return (year, month, day)

def add_days_to_date(y, m, d, n):
    day = d + n
    month = m
    year = y
    while day > 31:
        day -= 31
        month += 1
        if month > 12:
            month = 1
            year += 1
    while day < 1:
        month -= 1
        if month < 1:
            month = 12
            year -= 1
        day += 31
    return (year, month, day)

