def sum_of_prime_factors_with_multiplicity(n):
    def prime_factors(n):
        factors = []
        d = 2
        while d <= n:
            while n % d == 0:
                factors.append(d)
                n //= d
            d += 1
        return factors
    return sum(prime_factors(n))

